  "latest_incident_details": null,
  "sanitized_post_incident_report": {
    "title": "Post-Incident Sanitized Report (Draft)",
    "sections": {
      "Incident overview": "A webhook retry incident was observed following a recent billing update. The issue pertains to the webhook handling flow and is currently under investigation.",
      "Impact assessment": "No customer data exposure has been identified. Potential delays in webhook delivery for affected events; no system-wide outage reported.",
      "High-level timeline": "Billing update deployed. Webhook retries observed. Investigation initiated. Logs preserved for audit purposes. Remediation planning in progress.",
