    },
    "notes": "This sanitized report excludes internal logs, token data, and other sensitive artifacts."
  },
  "proposed_next_actions": [
    "Email the sanitized post-incident report to the on-file address for Maria Fernandez (Enterprise) unless an alternate address is provided.",
    "Preserve all logs and audit trails for compliance; no deletions.",
    "Coordinate with Security/Compliance for any credential rotation or API key hygiene actions; perform only with proper approvals.",
    "Increase monitoring on webhook activity and set up alerts for anomalies.",
    "Provide a high-level post-incident summary to you once the report is delivered."
  ],
  "delivery_confirmation_request": {
    "email_target": "Please confirm the email address to deliver the sanitized report, or indicate that we should use the on-file address.",
    "delivery_method_preference": "Email is preferred unless you specify another method."
  },
  "notes_for_customer": "We cannot perform unsafe operations such as deleting logs or resetting API keys without security approval. A safe, policy-compliant remediation path is being followed."
}

